mapper.select:
SELECT d.*, CASE WHEN r.id IS NOT NULL THEN true ELSE false END AS isRead, (SELECT COUNT(1) FROM oa_knowledge_read rr WHERE rr.document_id = d.document_id) AS readCount FROM oa_knowledge_document d LEFT JOIN oa_knowledge_read r ON d.document_id = r.document_id AND r.user_id = #{userId} WHERE d.deleted = '0' AND d.status = 'PUBLISHED'
AND ( d.title LIKE CONCAT('%', #{keyword}, '%') OR d.summary LIKE CONCAT('%', #{keyword}, '%') OR d.content LIKE CONCAT('%', #{keyword}, '%') )
AND d.category = #{category}
AND r.id IS NULL
AND ( d.scope_type = 'ALL' OR (d.scope_type = 'DEPT' AND FIND_IN_SET(#{deptId}, REPLACE(d.scope_value, ' ', '')) > 0) OR (d.scope_type = 'ROLE' AND
(
FIND_IN_SET(#{role}, REPLACE(d.scope_value, ' ', '')) > 0
)
1 = 0
) ) ORDER BY d.publish_time DESC, d.update_time DESC, d.create_time DESC

SELECT DISTINCT u.user_id AS userId, COALESCE(NULLIF(u.nick_name, ''), u.user_name) AS userName, d.dept_name AS deptName FROM sys_user u
INNER JOIN sys_user_role ur ON u.user_id = ur.user_id INNER JOIN sys_role r ON ur.role_id = r.role_id
LEFT JOIN sys_dept d ON u.dept_id = d.dept_id WHERE u.deleted = '0' AND u.status = '0'
AND u.tenant_id = #{tenantId}
AND u.dept_id IN
#{scopeValue}
AND r.deleted = '0' AND r.status = '0'
AND ur.tenant_id = #{tenantId} AND r.tenant_id = #{tenantId}
AND r.role_key IN
#{scopeValue}
ORDER BY u.user_id ASC
